import SwiftUI

private struct AnalystEnvelope: Decodable { let result: AnalystResult? }
private struct AnalystResult: Decodable {
    struct Asset: Decodable { let displaySymbol: String?; let name: String?; let quoteCurrency: String? }
    struct Price: Decodable { let available: Bool?; let value: Double?; let currency: String? }
    struct Completeness: Decodable { let percentage: Double?; let missingRequiredFactors: [String]? }
    let analysisId: String?; let recommendation: String?; let confidence: Double?; let confidenceQuality: String?; let risk: String?; let asset: Asset?; let marketPrice: Price?; let dataCompleteness: Completeness?
}
private struct AnalystChatEnvelope: Decodable { let ok: Bool?; let text: String? }
private struct AnalystSearchEnvelope: Decodable { let results: [AnalystSearchItem]? }
private struct AnalystSearchItem: Decodable, Identifiable { let symbol: String?; let displaySymbol: String?; let name: String?; let assetType: String?; let exchange: String?; let market: String?; let currency: String?; var id: String { displaySymbol ?? symbol ?? UUID().uuidString } }

/// Session-bound native analyst. Server APIs retain identity verification, AI allowance, market evidence and rate limits.
struct InvestorAdvancedAnalysisView: View {
    @EnvironmentObject private var auth: AuthSessionStore
    @AppStorage("sfm-language") private var language = "ar"
    @State private var query = ""; @State private var matches: [AnalystSearchItem] = []; @State private var symbol = ""; @State private var assetType = "STOCK"; @State private var exchange = ""; @State private var currency = ""
    @State private var result: AnalystResult?; @State private var question = ""; @State private var chat: [(Bool, String)] = []; @State private var loading = false; @State private var error = false
    private func tr(_ ar: String, _ en: String, _ fr: String) -> String { language == "ar" ? ar : language == "fr" ? fr : en }
    private var code: String { symbol.trimmingCharacters(in: .whitespacesAndNewlines).uppercased() }
    private var valid: Bool { code.range(of: "^[A-Z0-9.^=:_/-]{1,32}$", options: .regularExpression) != nil }
    private var asset: [String: Any] { var value: [String: Any] = ["symbol": code, "assetType": assetType]; if !exchange.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { value["exchange"] = exchange }; if !currency.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { value["quoteCurrency"] = currency.uppercased() }; return value }

    var body: some View { List {
        Section { Text(tr("محلل المستثمر", "Investor analyst", "Analyste investisseur")).font(.title3.weight(.semibold)); Text(tr("الاستحقاق والحدود والبيانات الموثقة تبقى في الخادم.", "Entitlements, limits and verified data remain on the server.", "Les droits, limites et données vérifiées restent côté serveur.")).font(.footnote).foregroundStyle(.secondary) }
        Section(tr("البحث", "Search", "Recherche")) { TextField(tr("الاسم أو الرمز", "Name or symbol", "Nom ou symbole"), text: $query); Button(tr("بحث", "Search", "Rechercher")) { Task { await search() } }.disabled(loading || query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty); ForEach(matches) { item in Button { choose(item) } label: { VStack(alignment: .leading) { Text(item.displaySymbol ?? item.symbol ?? "-"); Text(item.name ?? "").font(.caption).foregroundStyle(.secondary) } } } }
        Section(tr("تحليل كامل", "Full analysis", "Analyse complète")) { TextField(tr("الرمز", "Symbol", "Symbole"), text: $symbol).textInputAutocapitalization(.characters).autocorrectionDisabled(); Picker(tr("فئة الأصل", "Asset type", "Type d'actif"), selection: $assetType) { ForEach(["STOCK", "CRYPTO", "FOREX", "INDEX", "COMMODITY", "FUND"], id: \.self) { Text($0).tag($0) } }; TextField(tr("البورصة (اختياري)", "Exchange (optional)", "Bourse (facultatif)"), text: $exchange); TextField(tr("عملة التسعير (اختياري)", "Quote currency (optional)", "Devise de cotation (facultatif)"), text: $currency); Button(tr("حلل", "Analyze", "Analyser")) { Task { await analyze(false) } }.disabled(loading || !valid); if loading { ProgressView() }; if error { Text(tr("تعذر إتمام الطلب. تحقق من الاتصال والصلاحيات.", "The request could not finish. Check connection and permissions.", "La requête n'a pas pu aboutir. Vérifiez la connexion et les droits.")).foregroundStyle(.red) } }
        if let result { Section(tr("النتيجة", "Result", "Résultat")) { Text("\(result.asset?.displaySymbol ?? code)\(result.asset?.name.map { " — \($0)" } ?? "")").font(.headline); LabeledContent(tr("التوصية", "Recommendation", "Recommandation"), value: result.recommendation ?? "-"); LabeledContent(tr("المخاطر", "Risk", "Risque"), value: result.risk ?? "-"); if let confidence = result.confidence { LabeledContent(tr("الثقة", "Confidence", "Confiance"), value: "\(Int((confidence <= 1 ? confidence * 100 : confidence).rounded()))% \(result.confidenceQuality ?? "")") }; if result.marketPrice?.available == true { LabeledContent(tr("السعر الموثق", "Verified price", "Cours vérifié"), value: "\(result.marketPrice?.value?.formatted(.number) ?? "-") \(result.marketPrice?.currency ?? result.asset?.quoteCurrency ?? "")") }; if let percentage = result.dataCompleteness?.percentage { LabeledContent(tr("اكتمال البيانات", "Data completeness", "Complétude des données"), value: "\(Int(percentage.rounded()))%") }; if let missing = result.dataCompleteness?.missingRequiredFactors, !missing.isEmpty { Text(tr("العوامل الناقصة: ", "Missing factors: ", "Facteurs manquants : ") + missing.joined(separator: ", ")).font(.footnote).foregroundStyle(.secondary) }; Button(tr("تحديث آمن", "Refresh safely", "Actualiser prudemment")) { Task { await analyze(true) } }.disabled(loading) } }
        Section(tr("محادثة التحليل", "Analysis chat", "Discussion d'analyse")) { Text(tr("لا تُرسل إلا الرسالة والرمز؛ يتحقق الخادم من الهوية والبيانات.", "Only the message and asset are sent; the server verifies identity and data.", "Seuls le message et l'actif sont envoyés ; le serveur vérifie l'identité et les données.")).font(.footnote).foregroundStyle(.secondary); ForEach(Array(chat.enumerated()), id: \.offset) { row in VStack(alignment: .leading) { Text(row.element.0 ? tr("أنت", "You", "Vous") : tr("المحلل", "Analyst", "Analyste")).font(.caption).foregroundStyle(.secondary); Text(row.element.1) } }; TextField(tr("سؤالك", "Your question", "Votre question"), text: $question, axis: .vertical); Button(tr("إرسال", "Send", "Envoyer")) { Task { await sendChat() } }.disabled(loading || !valid || question.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty) }
    }.navigationTitle(tr("تحليل", "Analysis", "Analyse")).refreshable { await analyze(false) } }

    @MainActor private func search() async { loading = true; error = false; defer { loading = false }; do { let escaped = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? ""; let response: AnalystSearchEnvelope = try await APIClient.shared.get("/api/market/search?query=\(escaped)"); matches = response.results ?? [] } catch is CancellationError {} catch { error = true } }
    @MainActor private func analyze(_ force: Bool) async { guard valid, let token = await auth.validAccessToken() else { error = true; return }; loading = true; error = false; defer { loading = false }; do { let body: [String: Any] = ["asset": asset, "horizon": "SWING", "locale": language, "requestedModules": ["TECHNICAL", "FUNDAMENTAL", "SENTIMENT", "NEWS", "RISK", "SHARIA"], "source": "SMART_MARKET_ANALYSIS", "forceRefresh": force]; result = try await APIClient.authorized(accessToken: token).send("/api/intelligence/analyze", method: "POST", body: JSONSerialization.data(withJSONObject: body), as: AnalystEnvelope.self).result; error = result == nil } catch is CancellationError {} catch { error = true } }
    @MainActor private func sendChat() async { let message = question.trimmingCharacters(in: .whitespacesAndNewlines); guard valid, !message.isEmpty, let token = await auth.validAccessToken() else { error = true; return }; let messages = chat.map { ["role": $0.0 ? "user" : "assistant", "content": $0.1] } + [["role": "user", "content": message]]; chat.append((true, message)); question = ""; loading = true; error = false; defer { loading = false }; do { var body: [String: Any] = ["domain": "market", "messages": messages, "asset": ["symbol": code, "assetType": assetType], "locale": language, "sourceRoute": "/ai-analyst/assistant"]; if let analysisId = result?.analysisId { body["analysisId"] = analysisId }; let reply = try await APIClient.authorized(accessToken: token).send("/api/intelligence/chat", method: "POST", body: JSONSerialization.data(withJSONObject: body), as: AnalystChatEnvelope.self); guard reply.ok == true, let text = reply.text else { error = true; return }; chat.append((false, text)) } catch is CancellationError {} catch { error = true } }
    private func choose(_ item: AnalystSearchItem) { symbol = item.displaySymbol ?? item.symbol ?? symbol; assetType = ["CRYPTO", "FOREX", "INDEX"].contains(item.assetType?.uppercased() ?? "") ? item.assetType!.uppercased() : ["ETF", "FUND"].contains(item.assetType?.uppercased() ?? "") ? "FUND" : ["METAL", "COMMODITY"].contains(item.assetType?.uppercased() ?? "") ? "COMMODITY" : "STOCK"; exchange = item.exchange ?? item.market ?? ""; currency = item.currency ?? ""; matches = []; result = nil }
}
